import math

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    for d in range(3, math.isqrt(n) + 1, 2):
        if n % d == 0:
            return False
    return True
```

It checks divisibility only up to `sqrt(n)` (using integer `isqrt`), skipping even divisors after handling `2`, so it runs in roughly `O(sqrt(n))` time.
